SELECT sqft_bucket, pct_bangkok FROM (SELECT CASE WHEN sqft >= 12797 THEN 'high' WHEN sqft >= 5356 THEN 'mid' ELSE 'low' END AS sqft_bucket, ROUND((100 * SUM(CASE WHEN city = 'Bangkok' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_bangkok FROM stores GROUP BY CASE WHEN sqft >= 12797 THEN 'high' WHEN sqft >= 5356 THEN 'mid' ELSE 'low' END) AS s WHERE pct_bangkok < 36 ORDER BY sqft_bucket LIMIT 5;
